    <script>
      (function() {
        const origFetch = window.fetch.bind(window);
        window.fetch = async function(input, init) {
          try {
            const urlStr = typeof input === "string" ? input : (input && input.url ? input.url : String(input));
            if (urlStr.startsWith("/api/")) {
              const method = (init && init.method) ? init.method.toUpperCase() : "GET";
              let parsedBody = {};
              if (init && init.body && typeof init.body === "string") {
                try { parsedBody = JSON.parse(init.body); } catch (_e) { parsedBody = { raw: init.body }; }
              }
              const apiResp = await origFetch("/webhook/bananapod-api", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  endpoint: urlStr,
                  method: method,
                  payload: parsedBody
                })
              });
              return apiResp;
            }
          } catch (err) {
            console.warn("API bridge intercept notice:", err);
          }
          return origFetch(input, init);
        };

        async function gunzipB64(b64) {
          const binStr = atob(b64);
          const bytes = new Uint8Array(binStr.length);
          for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
          const ds = new DecompressionStream("gzip");
          const writer = ds.writable.getWriter();
          writer.write(bytes);
          writer.close();
          return await new Response(ds.readable).text();
        }

        const CSS_GZ_B64 = "";
        const JS_GZ_B64 = "_GOOGLE_DOC_OR_SHEET_";

        (async function bootApp() {
          const [cssText, jsText] = await Promise.all([
            gunzipB64(CSS_GZ_B64),
            gunzipB64(JS_GZ_B64)
          ]);
          const styleEl = document.createElement("style");
          styleEl.textContent = cssText;
          document.head.appendChild(styleEl);

          const blob = new Blob([jsText], { type: "text/javascript" });
          const scriptEl = document.createElement("script");
          scriptEl.type = "module";
          scriptEl.src = URL.createObjectURL(blob);
          document.body.appendChild(scriptEl);
        })();
      })();
    </script>
  </body>
</html>";
return [{ json: { html } }];

